26	 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
27	 * person; a claim that is not a correction names none. */
28	@Service
29	public class ClaimService {
30	
31	    private final ClaimRepository claims;
32	    private final ClaimLogRepository logs;
33	    private final PersonRepository people;
34	    private final RollupService rollup;
35	    private final SheetService sheets;
36	    private final PeriodRepository periods;
37	    private final SettingsService settings;
38	    private final Audit audit;
39	
40	    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
41	            PeriodRepository periods, SettingsService settings, Audit audit) {
42	        this.claims = claims;
43	        this.logs = logs;
44	        this.people = people;
45	        this.rollup = rollup;
46	        this.sheets = sheets;
47	        this.periods = periods;
48	        this.settings = settings;
49	        this.audit = audit;
50	    }
51	
52	    /** The sheet's claims, newest first. */
53	    @Transactional(readOnly = true)
54	    public List<Claim> list(String sheetId) {
55	        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
56	    }
57	
58	    /** The status logs of the claims, by claim id, each oldest first. */
59	    @Transactional(readOnly = true)
60	    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
61	        if (of.isEmpty()) return Map.of();
62	        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
63	                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
64	    }
65	
66	    @Transactional
67	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
68	            String corrects) {
69	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
70	        RollupService.Snapshot before = rollup.snapshot(sheetId);
71	        LocalDate dated = date != null ? date : sheets.today(sheetId);
72	        refuseClosed(sheetId, dated);
73	        person.requireClaimable(dated);
74	        refuseBadCorrection(sheetId, personId, amount, corrects);
75	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
76	        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated))));
77	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
78	        claim = claims.saveAndFlush(claim);
79	        log(user, person, claim);
80	        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
81	        rollup.recordSince(sheetId, user, before);
82	        return claim;
83	    }
84	
85	    @Transactional
86	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
87	            String corrects) {
88	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
89	        LocalDate dated = date != null ? date : sheets.today(sheetId);
90	        refuseClosed(sheetId, claim.getDate());
91	        refuseClosed(sheetId, dated);
92	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
93	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
94	                .orElseThrow(PersonNotFoundException::new);
95	        person.requireClaimable(dated);
96	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
97	        RollupService.Snapshot before = rollup.snapshot(sheetId);
98	        claim.setAmount(amount);
99	        claim.setCorrects(corrects);
100	        claim.setDate(dated);
101	        claim.setNote(noteOf(note));
102	        claims.flush();
103	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
104	        rollup.recordSince(sheetId, user, before);
105	        return claim;
106	    }
107	
108	    /** Move the claim to {@code next}; refused when its current status does not allow it (a PENDING
109	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
110	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
111	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
112	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
113	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
114	     * it. A voided claim keeps its number, if it had one. */
115	    @Transactional
116	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
117	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
118	        refuseClosed(sheetId, claim.getDate());
119	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
120	            throw new ClaimStatusChangeException();
121	        }
122	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
123	        RollupService.Snapshot before = rollup.snapshot(sheetId);
124	        String number = claim.getNumber();
125	        if (next == ClaimStatus.OPEN) {
126	            number = nextNumber(sheetId, claim.getDate());
127	            claim.setOpenedBy(user);
128	        }
129	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
130	                .orElseThrow(PersonNotFoundException::new);
131	        if (next == ClaimStatus.SETTLED) {
132	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
133	            BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
134	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
135	            else claim.setSettledDue(due);
136	        }
137	        claim.setStatus(next);
138	        claim.setNumber(number);
139	        claims.flush();
140	        log(user, person, claim);
141	        String event = switch (next) {
142	            case OPEN -> "CLAIM_OPENED";
143	            case PENDING -> "CLAIM_PENDING";
144	            case SETTLED -> "CLAIM_SETTLED";
145	            case VOID -> "CLAIM_VOIDED";
146	            case DRAFT -> throw new IllegalStateException();
147	        };
148	        if (next == ClaimStatus.SETTLED) {
149	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
150	        } else {
151	            record(event, user, person, claim, number);
152	        }
153	        rollup.recordSince(sheetId, user, before);
154	        return claim;
155	    }
156	
157	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
158	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
159	     * Refused unless the claim is PENDING, and when the user is not a steward or opened the claim. */
160	    @Transactional
161	    public Claim approve(String sheetId, String user, long claimId) {
162	        Claim claim = lockPending(sheetId, user, claimId);
163	        if (user.equals(claim.getOpenedBy())) throw new ClaimNotStewardException();
164	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
165	                .orElseThrow(PersonNotFoundException::new);
166	        RollupService.Snapshot before = rollup.snapshot(sheetId);
167	        BigDecimal figure = rollup.dueOf(claim, person);
168	        BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
169	        claim.setSettledDue(due);
170	        claim.setStatus(ClaimStatus.SETTLED);
171	        claims.flush();
172	        log(user, person, claim);
173	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
174	        rollup.recordSince(sheetId, user, before);
175	        return claim;
176	    }
177	
178	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
179	     * by its person's last statement if that statement included it. Refused unless the claim is
180	     * PENDING, and when the user is not a steward. */
181	    @Transactional
182	    public Claim reject(String sheetId, String user, long claimId, String reason) {
183	        Claim claim = lockPending(sheetId, user, claimId);
184	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
185	                .orElseThrow(PersonNotFoundException::new);
186	        RollupService.Snapshot before = rollup.snapshot(sheetId);
187	        claim.setStatus(ClaimStatus.OPEN);
188	        claims.flush();
189	        log(user, person, claim);
190	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
191	        rollup.recordSince(sheetId, user, before);
192	        return claim;
193	    }
194	
195	    /** A steward's move of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
196	     * number and date, loses any figure a statement bound it to (it is live again until its new
197	     * person's next statement), and is listed as its new person's newest claim. Refused when the user
198	     * is not a steward, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
199	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
200	     * is dated after the new person's retirement date. */
201	    @Transactional
202	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
203	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
204	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
205	        refuseClosed(sheetId, claim.getDate());
206	        ClaimStatus status = claim.getStatus();
207	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
208	                || claim.isCorrection() || claim.getPersonId() == personId) {
209	            throw new ClaimReassignException();
210	        }
211	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
212	                .orElseThrow(PersonNotFoundException::new);
213	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
214	        to.requireClaimable(claim.getDate());
215	        RollupService.Snapshot before = rollup.snapshot(sheetId);
216	        claim.setPersonId(to.getId());
217	        claim.unbind();
218	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
219	        claims.flush();
220	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
221	        rollup.recordSince(sheetId, user, before);
222	        return claim;
223	    }
224	
225	    /** The PENDING claim, locked, for a steward to approve or reject. */
226	    private Claim lockPending(String sheetId, String user, long claimId) {
227	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
228	        refuseClosed(sheetId, claim.getDate());
229	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
230	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
231	        return claim;
232	    }
233	
234	    private static String dueText(BigDecimal due) {
235	        return due == null ? "n/a" : due.toPlainString();
236	    }
237	
238	    /** The figure the claim shows and totals now, without its late charge; null when it has no figure
239	     * (see {@link RollupService#figureOf}). */
240	    public BigDecimal figureOf(Claim claim, Person person) {
241	        return rollup.figureOf(claim, person);
242	    }
243	
244	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
245	     * no figure (see {@link RollupService#shownOf}). */
246	    public BigDecimal shownOf(Claim claim, Person person) {
247	        return rollup.shownOf(claim, person);
248	    }
249	
250	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
251	     * it shows now. */
252	    private void log(String user, Person person, Claim claim) {
253	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
254	                rollup.shownOf(claim, person)));
255	    }
256	
257	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
258	     * then any {@code extra} fields. */
259	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
260	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
261	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
262	                "date=" + claim.getDate()));
263	        if (number != null) fields.add("number=" + number);
264	        fields.addAll(List.of(extra));
265	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
266	    }
267	
268	    /** The number a claim dated {@code date} is given when opened now: within the period containing
269	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
270	     * period, otherwise the next sheet-wide number. */
271	    private String nextNumber(String sheetId, LocalDate date) {
272	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
273	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
274	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
275	                .findFirst()
276	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
277	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
278	    }
279	
280	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
281	     * the user is a clerk and the due is above the sheet's clerk limit. */
282	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
283	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
284	        BigDecimal limit = settings.clerkLimit(sheetId);
285	        return limit != null && due.compareTo(limit) > 0;
286	    }
287	
288	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
289	     * the person, and a claim that names one without being a correction. */
290	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
291	        if (amount.signum() >= 0) {
292	            if (corrects != null) throw new ClaimCorrectionException();
293	            return;
294	        }
295	        if (corrects == null) throw new ClaimCorrectionException();
296	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
297	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
298	                .orElseThrow(ClaimCorrectionException::new);
299	    }
300	
301	    /** Refuse a change that touches {@code date} when a closed period of the sheet contains it. */
302	    private void refuseClosed(String sheetId, LocalDate date) {
303	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
304	    }
305	
306	    private static String noteOf(String note) {
307	        return note == null ? "" : note.trim();
308	    }
309	}
