import org.springframework.transaction.annotation.Transactional;

/**
 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
 * claims, leaving out the OPEN and PENDING ones dated within one of their holds that no statement binds)
 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
 * their grade is in force on the sheet's today, and at most the sheet's cap when it has one) and their
 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
 * sheet's today, as each shows it) — and the sheet's totals of them. A change that moves
 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
 * line when the sheet's totals moved: take a {@link #snapshot} before the change, and
 * {@link #recordSince} it after the change has recorded its own lines.
 */
@Service
public class RollupService {

    /** A due-total shown when there is none. */
    public static final String NONE = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** A person's figures, as shown. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    /** The figures the sheet shows now. */
    @Transactional(propagation = Propagation.MANDATORY)
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        BigDecimal cap = sheet == null ? null : sheet.getCap();
        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        BigDecimal overdueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean any = false;
            for (Claim claim : all) {
                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person)) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = shownOf(claim, person);
                if (figure == null) continue;
                if (isOverdue(claim, today)) overdue = overdue.add(figure);
                due = due.add(figure);
                any = true;
            }
            due = cappedOf(due, cap);
            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue);
            if (any || rated) dueTotal = dueTotal.add(due);
            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
                    text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(dueTotal), text(overdueTotal));
    }

    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void recordSince(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            Figures then = before.people().get(id);
            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
                    && then.overdueTotal().equals(now.overdueTotal())) return;
            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
        }
    }

    /** Whether the claim is overdue: OPEN or PENDING, and due by a date before the sheet's {@code today}. */
    public static boolean isOverdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
                && claim.getDueBy().isBefore(today);
    }

    /** A due-total as shown: at most {@code cap}, when there is one. */
    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
        return cap == null ? due : due.min(cap);
    }

    /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED, but not OPEN or PENDING
     * when it is dated within one of its person's holds and no statement binds it (a PENDING claim is
     * bound by none while it is). */
    public static boolean countsLive(Claim claim, Person person) {
        if (!claim.getStatus().counts()) return false;
        if (!claim.getStatus().isOpen()) return true;
        boolean bound = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
        return bound || !person.isHeldOn(claim.getDate());
    }

    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate;
     * otherwise, unless it is PENDING (which no statement binds while it is), the figure a statement
     * bound it to; otherwise what is due on it at its person's rate.
     * Null when it has no figure. */
    public BigDecimal figureOf(Claim claim, Person person) {
        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
        return dueOf(claim, person);
    }

    /** What is due on the claim as it shows and totals now: its figure, plus its late charge; null when
     * it has no figure. */
    public BigDecimal shownOf(Claim claim, Person person) {
        BigDecimal figure = figureOf(claim, person);
        return figure == null ? null : figure.add(lateChargeOf(claim, figure));
    }

    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: the sheet's late percent of that
     * figure for every full 30 days the claim is overdue (past its due-by, fixed when it was added, on
     * the sheet's today), rounded to two decimals as the claim rounds (see {@link #roundingOf}); 0.00 on a claim not OPEN or
     * PENDING, or not overdue, and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
        if (!claim.getStatus().isOpen() || claim.isCorrection()) return zero();
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        if (sheet == null) return zero();
        long periods = Math.max(0, ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday())) / 30;
        return figure.multiply(sheet.getLatePct()).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, roundingOf(claim, sheet));
    }

    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}), and at least the sheet's floor (a correction,
     * whose due is negative, has no floor); null when no
     * rate of the grade in force for them on the claim's date applies then. */
    public BigDecimal dueOf(Claim claim, Person person) {
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        BigDecimal floor = sheet == null ? zero() : sheet.getFloor();
        RoundingMode rounding = roundingOf(claim, sheet);
        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(floor))
                .orElse(null);
    }

    /** How the claim's live figures round: half up when it is dated before the sheet's policy date in
     * force, half to even when on or after it. A correction rounds by the date of the claim it corrects. */
    public RoundingMode roundingOf(Claim claim, Sheet sheet) {
        if (sheet == null) return RoundingMode.HALF_EVEN;
        LocalDate dated = claim.getDate();
        if (claim.isCorrection() && claim.getCorrects() != null) {
            dated = claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                    .map(Claim::getDate).orElse(dated);
        }
        return dated.isBefore(sheet.policyDateInForce()) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** A claim, with who opened it (null until opened), whether it is bound to the figure it had at its
     * person's last statement and its status log (one line per status it has had, oldest first); its amount, what was due on it when settled (null otherwise) and
     * the figure it is bound to (null when unbound or bound to no figure) are sent as text with two
     * decimals so they are never rounded on the way. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects, List<String> log) {
        /** The claims as views, each with its status log, in the order given. */
        public static List<ClaimView> allOf(List<Claim> claims, ClaimService service) {
            Map<Long, List<ClaimLog>> logs = service.logsOf(claims);
            return claims.stream().map(c -> of(c, logs.getOrDefault(c.getId(), List.of()))).toList();
        }

        /** The claim as a view, with its status log. */
        public static ClaimView of(Claim claim, ClaimService service) {
            return allOf(List.of(claim), service).get(0);
        }

        static ClaimView of(Claim claim, List<ClaimLog> log) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    text(claim.getSettledDue()), claim.getOpenedBy(), claim.isStated(), text(claim.getStatedDue()),
                    claim.getCorrects(), log.stream().map(ClaimView::line).toList());
        }

        /** A log line as shown: {@code <STATUS> by <user> on <date> due=<due>}. */
        private static String line(ClaimLog entry) {
            return entry.getStatus() + " by " + entry.getBy() + " on " + entry.getDate() + " due="
                    + (entry.getDue() == null ? "n/a" : text(entry.getDue()));
        }

        private static String text(BigDecimal figure) {
            return figure == null ? null : figure.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A claim's amount (with up to two decimals; negative on a correction), date (the sheet's today
     * when left out), note (may be empty) and, on a correction, the number of the claim it corrects. */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Size(max = 120) String corrects) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        /** The number named, trimmed; null when none is. */
        String correctsValue() {
            return corrects == null || corrects.isBlank() ? null : corrects.trim();
        }
    }

    /** Why a steward rejects a PENDING claim: one word, as it is written into the audit. */
    public record RejectRequest(@NotNull @Pattern(regexp = "\\s*\\S{1,200}\\s*") String reason) {
    }

    /** The person a claim is moved to, by id. */
    public record ReassignRequest(@NotNull Long personId) {
    }

    /** The claims a bulk change is asked of, by id. */
    public record BulkRequest(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    /** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
    public record BulkOpenView(int opened, int refused, List<ClaimView> claims) {
    }

    /** How a bulk settle went: how many claims it settled (or left PENDING) and refused, and those claims. */
    public record BulkSettleView(int settled, int refused, List<ClaimView> claims) {
    }

    private final ClaimService service;
    private final ClaimBulkService bulk;

    public ClaimController(ClaimService service, ClaimBulkService bulk) {
        this.service = service;
        this.bulk = bulk;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return views(service.list(sheetId.trim()));
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
                request.note(), request.correctsValue()));
    }

    @PutMapping("/claims/{claimId}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), claimId, request.amountValue(), request.date(),
                request.note(), request.correctsValue()));
    }

    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.approve(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RejectRequest request) {
        return view(service.reject(sheetId.trim(), user.trim(), claimId, request.reason().trim()));
    }

    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.VOID));
    }

    @PostMapping("/claims/{claimId}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ReassignRequest request) {
        return view(service.reassign(sheetId.trim(), user.trim(), claimId, request.personId()));
    }

    @PostMapping("/claims/bulk-open")
    public BulkOpenView bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkRequest request) {
        ClaimBulkService.Outcome outcome = bulk.open(sheetId.trim(), user.trim(), request.claimIds());
        return new BulkOpenView(outcome.changed().size(), outcome.refused(),
                views(outcome.changed()));
    }

    @PostMapping("/claims/bulk-settle")
    public BulkSettleView bulkSettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkRequest request) {
        ClaimBulkService.Outcome outcome = bulk.settle(sheetId.trim(), user.trim(), request.claimIds());
        return new BulkSettleView(outcome.changed().size(), outcome.refused(),
                views(outcome.changed()));
    }

    private ClaimView view(Claim claim) {
        return ClaimView.of(claim, service);
    }

    private List<ClaimView> views(List<Claim> claims) {
        return ClaimView.allOf(claims, service);
    }
}

